  <?= Ui::formConfirmar(url('admin-acao'), ['tipo' => 'email-teste', 'ret' => 'admin-config'], 'Enviar e-mail de teste para ' . $adm['email'], 'Enviar e-mail de teste?', 'Uma mensagem de teste será enviada para ' . $adm['email'] . '.', 'primary', 'ui-btn') ?>
